import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { cache as requestCache } from "react";
import { withBase } from "@/lib/base-path";
import { type DataDirs, DEFAULT_PROJECT, dataDirs, getProject } from "@/lib/projects";

/**
 * Read-only access to the code system for the QC hub (/hub): clusters, registries, requirement
 * Markdown, the Figma frame map and the screen → requirement pages map. Everything is generated by
 * scripts/he-thong-ma and committed, so the hub always shows what is on main. Loaded once per project and instance.
 * Every reader takes the project slug last (lib/projects.ts); without it, the project of this request
 * (set by hubProject() in lib/qc/project.ts from the hub's project picker), else ICS. Projects without data
 * folders in this repo are built live from their docs repo and Figma scan (lib/qc/remote.ts) and primed here.
 */

/** The project this request shows: one object per server render (React cache), ICS outside a render. */
export const requestProject = requestCache((): { slug: string } => ({ slug: DEFAULT_PROJECT }));
const current = (): string => requestProject().slug;

const ROOT = /* turbopackIgnore: true */ process.cwd();

/** Absolute folder of a project's requirement Markdown. */
export function reqDir(project: string = current()): string {
  const p = getProject(project);
  if (!p) throw new Error(`Không có dự án ${project}.`);
  return join(/* turbopackIgnore: true */ ROOT, dataDirs(p).requirements);
}

export type Match = { term: string; figmaId: string; layer: string; confidence: string; component: string | null };
export type Item = {
  id: string;
  label: string;
  spec: string;
  status?: string;
  matches: Record<string, Match[]>;
  testcases?: string[];
};
export type Region = { id: string; title: string; screens: string[]; requirement?: string; needsDesign?: boolean; items: Item[] };
export type Testcase = {
  id: string;
  title: string;
  priority: string;
  smoke: boolean;
  region: string | null;
  scenario: string;
  requirements: string[];
  exceptions: string[];
  flows: string[];
  items: string[];
};
export type Requirement = { id: string; name?: string; text: string };
export type Screen = {
  id: string;
  title: string;
  kind: string;
  parent?: string | null;
  nodeId?: string;
  inFigma?: boolean;
  route?: string;
  link?: string;
  regions?: string[];
};
export type Registry = {
  cluster: string;
  title: string;
  requirements: Requirement[];
  exceptions: Requirement[];
  screens: Record<string, Screen>;
  regions: Region[];
  testcases: Testcase[];
  issues: { kind: string; ref: string; text: string }[];
  requirementFiles: { file: string; prefix: string; title: string }[];
};
export type Frame = { id: string; title: string; loai: string; parent?: string | null };
export type ReqPage = { file: string; prefix: string; title: string; pages: number[] };
export type Reserved = Record<string, { title?: string; requirement?: string; pages?: string[] }>;
/** A row of the "Danh sách màn hình" table on Figma's NAVIGATION page (scripts/he-thong-ma/navigation.py). */
export type NavRow = { code: string; title: string; node: string | null; type: string; page: string; final: boolean; todo: boolean; removed: boolean; loai: string; group: string };

const json = <T,>(path: string, fallback: T): T => (existsSync(path) ? (JSON.parse(readFileSync(path, "utf-8")) as T) : fallback);

export type Data = {
  clusters: { name: string; title: string }[];
  registries: Map<string, Registry>;
  frames: Record<string, Frame>;
  fileKey: string;
  screenReq: Record<string, ReqPage[]>;
  reserved: Reserved;
  index: QcIndex;
  pages: Map<string, string>;
  nav: Record<string, NavRow>;
  sys: string;
  req: string;
  /** Requirement Markdown held in memory (live projects), by path. */
  docs?: Map<string, string>;
  /** trang-chua-gan-ma.md held in memory (live projects). */
  unmapped?: string;
};
const cache = new Map<string, Data>();

/** Data of a live project, built elsewhere; replaces what was there. */
export const prime = (project: string, data: Data): void => void cache.set(project, data);

export type IndexFile = { path: string; title: string; prefix: string; screens: string[]; pages: { no: number; title: string; screens: string[] }[] };
type QcIndex = { version?: string; generatedAt?: string; files?: IndexFile[] };

/** Reads one file of a project's code system (repo-relative path); the fallback when it is not there. */
export type Reader = <T>(path: string, fallback: T) => T;

/**
 * A project's data from its generated code system, the files scripts/he-thong-ma writes: ICS reads them from
 * disk, a hub-added project from main through GitHub (lib/qc/remote.ts). `dirs` are repo-relative.
 */
export function assemble(read: Reader, dirs: DataDirs, fileKey: string): Data {
  const sys = (name: string) => `${dirs.sys}/${name}`;
  const clusters = read<{ clusters: { name: string; title: string }[] }>(sys("clusters.json"), { clusters: [] }).clusters;
  const registries = new Map<string, Registry>();
  for (const c of clusters) {
    const r = read<Partial<Registry> | null>(sys(`${c.name}.registry.json`), null);
    // Figma-only clusters have no requirement side: fill the lists so pages need no checks
    if (r)
      registries.set(c.name, {
        cluster: c.name,
        title: c.title,
        screens: {},
        requirements: [],
        exceptions: [],
        regions: [],
        testcases: [],
        issues: [],
        requirementFiles: [],
        ...r,
      } as Registry);
  }
  const frames = read<{ fileKey: string; frames: Record<string, Frame> }>(sys("figma-frames.json"), { fileKey: "", frames: {} });
  const nav = read<{ codes: Record<string, NavRow> }>(sys("navigation.json"), { codes: {} }).codes;
  // codes in the NAVIGATION table whose frame is not named with the code yet still count as screens
  for (const r of Object.values(nav))
    if (!r.removed && !frames.frames[r.code] && r.node) frames.frames[r.code] = { id: r.node, title: r.title, loai: r.loai };
  return {
    clusters: clusters.filter((c) => registries.has(c.name)).map((c) => ({ name: c.name, title: c.title })),
    registries,
    frames: frames.frames,
    fileKey: frames.fileKey || fileKey,
    screenReq: read(dirs.screenReq, {}),
    reserved: read<{ codes: Reserved }>(sys("ma-du-kien.json"), { codes: {} }).codes,
    index: read(sys("qc-index.json"), {}),
    nav,
    pages: new Map(dirs.pages ? read<{ pages: { name: string; route: string }[] }>(dirs.pages, { pages: [] }).pages.map((x) => [x.name, x.route]) : []),
    sys: join(/* turbopackIgnore: true */ ROOT, dirs.sys),
    req: join(/* turbopackIgnore: true */ ROOT, dirs.requirements),
  };
}

function load(project: string = current()): Data {
  const hit = cache.get(project);
  if (hit) return hit;
  const p = getProject(project);
  if (!p) throw new Error(`Không có dự án ${project}.`);
  const data = assemble((path, fallback) => json(join(/* turbopackIgnore: true */ ROOT, path), fallback), dataDirs(p), p.fileKey);
  cache.set(project, data);
  return data;
}

export const clusters = (project?: string): { name: string; title: string }[] => load(project).clusters;
export const registry = (name: string, project?: string): Registry | undefined => load(project).registries.get(name);
export const frames = (project?: string): Record<string, Frame> => load(project).frames;
export const reserved = (project?: string): Reserved => load(project).reserved;
/** The code's row in the NAVIGATION table (Final, Chưa làm, Đã bỏ, nhóm), if design listed it there. */
export const navRow = (code: string, project?: string): NavRow | undefined => load(project).nav[code.replace(/-DK$/, "")];
export const indexInfo = (project?: string): QcIndex => load(project).index;
/** Every requirement file (docs/he-thong-ma/qc-index.json), path without the "requirements/" prefix. */
export const requirementFiles = (project?: string): IndexFile[] => (load(project).index.files ?? []).map((f) => ({ ...f, path: f.path.replace(/^requirements\//, "") }));
export const figmaUrl = (nodeId: string, project?: string): string =>
  `https://www.figma.com/design/${load(project).fileKey}/?node-id=${nodeId.replace(":", "-")}`;
/** Built page of a screen (figma.pages.json name = code in lower case): demo route, generated code and Markdown spec. */
export function builtPage(code: string, project?: string): { code: string; spec: string; route: string } | null {
  const name = code.toLowerCase();
  const route = load(project).pages.get(name);
  return route ? { code: `/figma/${name}/code`, spec: `/figma/${name}/spec`, route } : null;
}
export const liveImage = (code: string): string => withBase(`/api/figma-frame/${code}.png`);

export type ClusterStats = { screens: number; files: number; items: number; testcases: number; matched: number; issues: number };

export function stats(r: Registry): ClusterStats {
  // layers Figma has but no requirement row names (F01…) are not requirement items
  const items = r.regions.flatMap((g) => g.items).filter((i) => i.status !== "chi-co-tren-figma");
  return {
    screens: Object.values(r.screens).filter((s) => !s.id.endsWith("-DK")).length,
    files: r.requirementFiles.length,
    items: items.length,
    testcases: r.testcases.length,
    matched: items.filter((i) => ["khop", "khop-mot-phan", "req-ghi-thieu-nhung-figma-co"].includes(i.status ?? "")).length,
    issues: r.issues.length,
  };
}

/** Clusters that contain a screen code. */
export function clustersOf(code: string, project?: string): { name: string; title: string }[] {
  return clusters(project).filter((c) => registry(c.name, project)?.screens[code]);
}

/** Requirement pages that talk about a screen (or its parent, for a popup). */
export const requirementPages = (code: string, project?: string): ReqPage[] => load(project).screenReq[code] ?? [];

/** Cluster whose registry carries a requirement file. */
export function clusterOfFile(file: string, project?: string): string | undefined {
  return clusters(project).find((c) => registry(c.name, project)?.requirementFiles.some((f) => f.file === file))?.name;
}

export function requirementMarkdown(file: string, project?: string): string | null {
  const data = load(project);
  if (data.docs) return data.docs.get(file) ?? null;
  const dir = data.req;
  const path = join(dir, file);
  if (!path.startsWith(dir) || !existsSync(path)) return null;
  return readFileSync(path, "utf-8");
}

export function unmappedPages(project?: string): { file: string; page: string; reason: string; candidates: string }[] {
  const data = load(project);
  let text = data.unmapped;
  if (text === undefined) {
    const path = data.sys ? join(data.sys, "trang-chua-gan-ma.md") : "";
    text = path && existsSync(path) ? readFileSync(path, "utf-8") : "";
  }
  return text
    .split("\n")
    .filter((l) => l.startsWith("| `"))
    .map((l) => {
      const [file, page, reason, candidates] = l.split("|").slice(1, 5).map((c) => c.trim().replace(/`/g, ""));
      return { file, page, reason, candidates };
    });
}

export type Hit = { kind: "cụm" | "màn" | "item" | "yêu cầu" | "testcase" | "tài liệu"; code: string; title: string; href: string; sub?: string };

/** Search codes and names across every cluster: screens, items, REQ/EX and testcases. */
export function search(q: string, limit = 60, project?: string): Hit[] {
  const needle = q.trim().toLowerCase();
  if (!needle) return [];
  const hit = (s: string | undefined) => !!s && s.toLowerCase().includes(needle);
  const out: Hit[] = [];
  const seenScreens = new Set<string>();
  for (const c of clusters(project)) {
    const r = registry(c.name, project)!;
    if (hit(c.title) || hit(c.name)) out.push({ kind: "cụm", code: c.name, title: c.title, href: `/hub/cum/${c.name}` });
    for (const s of Object.values(r.screens)) {
      if (!seenScreens.has(s.id) && (hit(s.id) || hit(s.title))) {
        seenScreens.add(s.id);
        out.push({ kind: "màn", code: s.id, title: s.title, href: `/hub/man/${s.id}`, sub: c.title });
      }
    }
    for (const g of r.regions)
      for (const i of g.items)
        if (hit(i.id) || hit(i.label)) out.push({ kind: "item", code: i.id, title: i.label, href: `/hub/cum/${c.name}?tab=item#${i.id}`, sub: g.title });
    for (const q2 of [...r.requirements, ...r.exceptions])
      if (hit(q2.id) || hit(q2.name)) out.push({ kind: "yêu cầu", code: q2.id, title: q2.name ?? q2.text, href: `/hub/cum/${c.name}?tab=testcase&req=${q2.id}`, sub: c.title });
    for (const t of r.testcases)
      if (hit(t.id) || hit(t.title)) out.push({ kind: "testcase", code: t.id, title: t.title, href: `/hub/cum/${c.name}?tab=testcase#${t.id}`, sub: c.title });
    if (out.length >= limit * 3) break;
  }
  // full text of the documents: one hit per file, the first matching line as the snippet
  if (needle.length >= 3)
    for (const f of requirementFiles(project)) {
      const text = requirementMarkdown(f.path, project);
      const at = text?.toLowerCase().indexOf(needle) ?? -1;
      if (!text || at < 0) continue;
      const line = text.slice(text.lastIndexOf("\n", at) + 1, (text.indexOf("\n", at) + 1 || text.length + 1) - 1).replace(/[#*`>|_[\]]/g, " ").replace(/\s+/g, " ").trim();
      out.push({ kind: "tài liệu", code: f.prefix || "—", title: f.title, href: `/hub/docs?f=${encodeURIComponent(f.path)}`, sub: line.slice(0, 160) });
    }
  const order = { "cụm": 0, "tài liệu": 1, "yêu cầu": 2, "màn": 3, "item": 4, testcase: 5 };
  return out.sort((a, b) => order[a.kind] - order[b.kind]).slice(0, limit);
}
